CREATE TABLE IF NOT EXISTS packages (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, speed_mbps INTEGER NOT NULL, price REAL NOT NULL, duration_days INTEGER DEFAULT 30, description TEXT, is_active INTEGER DEFAULT 1, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS staff (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, phone TEXT, role TEXT DEFAULT 'staff', department TEXT DEFAULT 'operations', salary REAL DEFAULT 0, is_active INTEGER DEFAULT 1, hire_date TEXT DEFAULT (datetime('now')), created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS customers (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, phone TEXT NOT NULL, email TEXT, address TEXT, package_id INTEGER, connection_date TEXT, status TEXT DEFAULT 'active', monthly_bill REAL DEFAULT 0, balance REAL DEFAULT 0, notes TEXT, portal_username TEXT, portal_password TEXT, portal_active INTEGER DEFAULT 0, last_login TEXT, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS invoices (id INTEGER PRIMARY KEY AUTOINCREMENT, invoice_number TEXT UNIQUE NOT NULL, customer_id INTEGER NOT NULL, package_id INTEGER, amount REAL NOT NULL, status TEXT DEFAULT 'unpaid', issue_date TEXT DEFAULT (datetime('now')), due_date TEXT, paid_date TEXT, payment_method TEXT, notes TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY AUTOINCREMENT, invoice_id INTEGER NOT NULL, customer_id INTEGER NOT NULL, amount REAL NOT NULL, payment_method TEXT, transaction_id TEXT, payment_date TEXT DEFAULT (datetime('now')), created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS tickets (id INTEGER PRIMARY KEY AUTOINCREMENT, ticket_number TEXT UNIQUE NOT NULL, customer_id INTEGER NOT NULL, subject TEXT NOT NULL, description TEXT, priority TEXT DEFAULT 'medium', status TEXT DEFAULT 'open', assigned_to INTEGER, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')), resolved_at TEXT);
CREATE TABLE IF NOT EXISTS network_devices (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, type TEXT NOT NULL, brand TEXT, model TEXT, serial_number TEXT, ip_address TEXT, mac_address TEXT, location TEXT, port_count INTEGER DEFAULT 0, ports_used INTEGER DEFAULT 0, firmware_version TEXT, status TEXT DEFAULT 'online', installed_date TEXT, last_seen TEXT, notes TEXT, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS device_ports (id INTEGER PRIMARY KEY AUTOINCREMENT, device_id INTEGER NOT NULL, port_number INTEGER NOT NULL, port_name TEXT, connected_customer_id INTEGER, connected_device_id INTEGER, status TEXT DEFAULT 'available', speed TEXT, notes TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS network_monitoring (id INTEGER PRIMARY KEY AUTOINCREMENT, device_id INTEGER NOT NULL, status TEXT NOT NULL, uptime_seconds INTEGER, latency_ms REAL, bandwidth_usage_mbps REAL, cpu_usage REAL, memory_usage REAL, temperature_c REAL, checked_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS inventory_items (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, category TEXT NOT NULL, sku TEXT UNIQUE, unit TEXT DEFAULT 'pcs', quantity INTEGER DEFAULT 0, min_quantity INTEGER DEFAULT 5, unit_price REAL DEFAULT 0, total_value REAL DEFAULT 0, warehouse_location TEXT, supplier TEXT, notes TEXT, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS inventory_transactions (id INTEGER PRIMARY KEY AUTOINCREMENT, item_id INTEGER NOT NULL, type TEXT NOT NULL, quantity INTEGER NOT NULL, unit_price REAL, reference TEXT, staff_id INTEGER, notes TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS employee_attendance (id INTEGER PRIMARY KEY AUTOINCREMENT, staff_id INTEGER NOT NULL, date TEXT NOT NULL, check_in TEXT, check_out TEXT, status TEXT DEFAULT 'present', work_hours REAL DEFAULT 0, overtime_hours REAL DEFAULT 0, notes TEXT, created_at TEXT DEFAULT (datetime('now')), UNIQUE(staff_id, date));
CREATE TABLE IF NOT EXISTS leave_requests (id INTEGER PRIMARY KEY AUTOINCREMENT, staff_id INTEGER NOT NULL, leave_type TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, days REAL NOT NULL, reason TEXT, status TEXT DEFAULT 'pending', approved_by INTEGER, approved_at TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS payroll (id INTEGER PRIMARY KEY AUTOINCREMENT, staff_id INTEGER NOT NULL, month TEXT NOT NULL, basic_salary REAL, overtime_pay REAL DEFAULT 0, deductions REAL DEFAULT 0, bonus REAL DEFAULT 0, net_salary REAL, status TEXT DEFAULT 'pending', paid_date TEXT, created_at TEXT DEFAULT (datetime('now')), UNIQUE(staff_id, month));
CREATE TABLE IF NOT EXISTS bandwidth_usage (id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id INTEGER NOT NULL, date TEXT NOT NULL, download_bytes INTEGER DEFAULT 0, upload_bytes INTEGER DEFAULT 0, total_bytes INTEGER DEFAULT 0, download_mbps REAL DEFAULT 0, upload_mbps REAL DEFAULT 0, peak_download_mbps REAL DEFAULT 0, online_hours REAL DEFAULT 0, ip_address TEXT, created_at TEXT DEFAULT (datetime('now')), UNIQUE(customer_id, date));
CREATE TABLE IF NOT EXISTS bandwidth_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id INTEGER NOT NULL, session_start TEXT NOT NULL, session_end TEXT, duration_sec INTEGER DEFAULT 0, download_bytes INTEGER DEFAULT 0, upload_bytes INTEGER DEFAULT 0, avg_download_mbps REAL, ip_address TEXT, status TEXT DEFAULT 'active', created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT, updated_at TEXT DEFAULT (datetime('now')));
INSERT OR IGNORE INTO settings (key, value) VALUES ('retention_daily_days','1095'),('retention_session_days','90'),('company_name','My ISP'),('currency','BDT');
CREATE TABLE IF NOT EXISTS system_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, level TEXT NOT NULL, category TEXT NOT NULL, message TEXT NOT NULL, entity_type TEXT, entity_id INTEGER, staff_id INTEGER, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS customer_orders (id INTEGER PRIMARY KEY AUTOINCREMENT, order_number TEXT UNIQUE NOT NULL, customer_id INTEGER NOT NULL, order_type TEXT NOT NULL, reference_type TEXT, reference_id INTEGER, description TEXT, quantity INTEGER DEFAULT 1, unit_price REAL NOT NULL, total_amount REAL NOT NULL, discount REAL DEFAULT 0, final_amount REAL NOT NULL, payment_status TEXT DEFAULT 'pending', payment_method TEXT, staff_id INTEGER, notes TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS order_items (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL, item_name TEXT NOT NULL, item_type TEXT, quantity INTEGER DEFAULT 1, unit_price REAL NOT NULL, total_price REAL NOT NULL, notes TEXT);
CREATE TABLE IF NOT EXISTS customer_refunds (id INTEGER PRIMARY KEY AUTOINCREMENT, refund_number TEXT UNIQUE NOT NULL, customer_id INTEGER NOT NULL, order_id INTEGER, amount REAL NOT NULL, reason TEXT, refund_method TEXT, status TEXT DEFAULT 'pending', requested_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS package_changes (id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id INTEGER NOT NULL, old_package_id INTEGER, new_package_id INTEGER, old_package_name TEXT, new_package_name TEXT, change_type TEXT NOT NULL, old_price REAL, new_price REAL, price_difference REAL, requested_by TEXT DEFAULT 'customer', staff_id INTEGER, notes TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS password_changes (id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id INTEGER NOT NULL, change_type TEXT NOT NULL, old_value_hash TEXT, new_value_hash TEXT, changed_by TEXT DEFAULT 'customer', staff_id INTEGER, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS olt_pon_ports (id INTEGER PRIMARY KEY AUTOINCREMENT, device_id INTEGER NOT NULL, pon_number INTEGER NOT NULL, pon_name TEXT, slot_number INTEGER, board_type TEXT, total_ont_ports INTEGER DEFAULT 64, used_ont_ports INTEGER DEFAULT 0, available_ont_ports INTEGER DEFAULT 64, tx_power_dbm REAL, rx_power_dbm REAL, status TEXT DEFAULT 'active', customer_count INTEGER DEFAULT 0, notes TEXT, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS pon_port_customers (id INTEGER PRIMARY KEY AUTOINCREMENT, pon_port_id INTEGER NOT NULL, device_id INTEGER NOT NULL, customer_id INTEGER NOT NULL, ont_id TEXT, ont_name TEXT, ont_port_number INTEGER, ont_serial TEXT, ont_model TEXT, ont_status TEXT DEFAULT 'online', ont_rx_power_dbm REAL, ont_tx_power_dbm REAL, ont_distance_m REAL, vlan_id INTEGER, ip_address TEXT, description TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS pon_power_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, pon_port_id INTEGER NOT NULL, device_id INTEGER NOT NULL, tx_power_dbm REAL, rx_power_dbm REAL, avg_ont_rx_power REAL, min_ont_rx_power REAL, max_ont_rx_power REAL, online_ont_count INTEGER DEFAULT 0, offline_ont_count INTEGER DEFAULT 0, total_ont_count INTEGER DEFAULT 0, temperature_c REAL, voltage_v REAL, checked_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS splitters (id INTEGER PRIMARY KEY AUTOINCREMENT, pon_port_id INTEGER NOT NULL, name TEXT NOT NULL, split_ratio TEXT NOT NULL, output_count INTEGER NOT NULL, used_outputs INTEGER DEFAULT 0, available_outputs INTEGER, location TEXT, type TEXT DEFAULT 'plc', insertion_loss_db REAL, status TEXT DEFAULT 'active', notes TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS splitter_port_customers (id INTEGER PRIMARY KEY AUTOINCREMENT, splitter_id INTEGER NOT NULL, output_port_number INTEGER NOT NULL, customer_id INTEGER NOT NULL, customer_name TEXT, ont_serial TEXT, fiber_cable_length_m REAL, connector_type TEXT, status TEXT DEFAULT 'connected', notes TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS bw_providers (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, company TEXT, contact_person TEXT, phone TEXT, email TEXT, bandwidth_mbps REAL NOT NULL, cost_per_mbps REAL NOT NULL, monthly_cost REAL NOT NULL, contract_start TEXT, contract_end TEXT, status TEXT DEFAULT 'active', notes TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS bw_allocation (id INTEGER PRIMARY KEY AUTOINCREMENT, provider_id INTEGER NOT NULL, total_mbps REAL NOT NULL, allocated_mbps REAL DEFAULT 0, reserved_mbps REAL DEFAULT 0, available_mbps REAL DEFAULT 0, period TEXT NOT NULL, notes TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS bw_resellers (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, company TEXT, phone TEXT NOT NULL, email TEXT, address TEXT, allocated_mbps REAL NOT NULL, used_mbps REAL DEFAULT 0, rate_per_mbps REAL NOT NULL, monthly_bill REAL DEFAULT 0, balance REAL DEFAULT 0, status TEXT DEFAULT 'active', contract_date TEXT, notes TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS reseller_customers (id INTEGER PRIMARY KEY AUTOINCREMENT, reseller_id INTEGER NOT NULL, name TEXT NOT NULL, phone TEXT NOT NULL, address TEXT, speed_mbps REAL NOT NULL, monthly_bill REAL, status TEXT DEFAULT 'active', connection_date TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS reseller_invoices (id INTEGER PRIMARY KEY AUTOINCREMENT, invoice_number TEXT UNIQUE NOT NULL, reseller_id INTEGER NOT NULL, amount REAL NOT NULL, mbps_used REAL, period TEXT NOT NULL, status TEXT DEFAULT 'unpaid', issue_date TEXT DEFAULT (datetime('now')), due_date TEXT, paid_date TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS payment_gateways (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, display_name TEXT NOT NULL, api_key TEXT, api_secret TEXT, merchant_id TEXT, store_id TEXT, sandbox INTEGER DEFAULT 0, is_active INTEGER DEFAULT 0, config TEXT, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS gateway_transactions (id INTEGER PRIMARY KEY AUTOINCREMENT, transaction_id TEXT UNIQUE NOT NULL, gateway TEXT NOT NULL, customer_id INTEGER, invoice_id INTEGER, amount REAL NOT NULL, currency TEXT DEFAULT 'BDT', status TEXT DEFAULT 'pending', gateway_trx_id TEXT, payer_reference TEXT, payer_msisdn TEXT, payment_url TEXT, response_data TEXT, created_at TEXT DEFAULT (datetime('now')), completed_at TEXT);
CREATE TABLE IF NOT EXISTS customer_locations (id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id INTEGER NOT NULL UNIQUE, latitude REAL NOT NULL, longitude REAL NOT NULL, address TEXT, area TEXT, zone TEXT, landmark TEXT, marker_color TEXT DEFAULT 'green', marker_icon TEXT DEFAULT 'wifi', accuracy_m REAL, verified INTEGER DEFAULT 0, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS device_locations (id INTEGER PRIMARY KEY AUTOINCREMENT, device_id INTEGER NOT NULL UNIQUE, latitude REAL NOT NULL, longitude REAL NOT NULL, address TEXT, area TEXT, installation_type TEXT, height_m REAL, marker_icon TEXT DEFAULT 'router', created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS coverage_areas (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, description TEXT, color TEXT DEFAULT '#2563eb', fill_opacity REAL DEFAULT 0.2, polygon_coordinates TEXT NOT NULL, center_lat REAL, center_lng REAL, radius_m REAL, shape_type TEXT DEFAULT 'polygon', customer_count INTEGER DEFAULT 0, status TEXT DEFAULT 'active', created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS zones (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, description TEXT, center_lat REAL, center_lng REAL, radius_m REAL, color TEXT DEFAULT '#2563eb', customer_count INTEGER DEFAULT 0, device_count INTEGER DEFAULT 0, staff_id INTEGER, status TEXT DEFAULT 'active', created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS network_connections (id INTEGER PRIMARY KEY AUTOINCREMENT, from_device_id INTEGER NOT NULL, to_device_id INTEGER, to_customer_id INTEGER, connection_type TEXT NOT NULL, from_port TEXT, to_port TEXT, cable_type TEXT, cable_length_m REAL, connector_type TEXT, bandwidth_mbps REAL, latency_ms REAL, status TEXT DEFAULT 'active', cable_color TEXT, path_coordinates TEXT, notes TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS fiber_routes (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, from_device_id INTEGER, to_device_id INTEGER, from_location TEXT, to_location TEXT, cable_type TEXT DEFAULT 'single_mode', core_count INTEGER DEFAULT 4, used_cores INTEGER DEFAULT 0, available_cores INTEGER DEFAULT 4, cable_length_m REAL, path_coordinates TEXT NOT NULL, color TEXT DEFAULT '#f59e0b', status TEXT DEFAULT 'active', installed_date TEXT, notes TEXT, created_at TEXT DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_customers_status ON customers(status);
CREATE INDEX IF NOT EXISTS idx_invoices_customer ON invoices(customer_id);
CREATE INDEX IF NOT EXISTS idx_invoices_status ON invoices(status);
CREATE INDEX IF NOT EXISTS idx_tickets_customer ON tickets(customer_id);
CREATE INDEX IF NOT EXISTS idx_tickets_status ON tickets(status);
CREATE INDEX IF NOT EXISTS idx_devices_type ON network_devices(type);
CREATE INDEX IF NOT EXISTS idx_devices_status ON network_devices(status);
CREATE INDEX IF NOT EXISTS idx_inventory_cat ON inventory_items(category);
CREATE INDEX IF NOT EXISTS idx_attendance_staff ON employee_attendance(staff_id);
CREATE INDEX IF NOT EXISTS idx_bw_customer ON bandwidth_usage(customer_id);
CREATE INDEX IF NOT EXISTS idx_logs_level ON system_logs(level);
CREATE INDEX IF NOT EXISTS idx_logs_category ON system_logs(category);
CREATE INDEX IF NOT EXISTS idx_orders_customer ON customer_orders(customer_id);
CREATE INDEX IF NOT EXISTS idx_pon_device ON olt_pon_ports(device_id);
CREATE INDEX IF NOT EXISTS idx_pon_cust_customer ON pon_port_customers(customer_id);
CREATE INDEX IF NOT EXISTS idx_cust_loc_customer ON customer_locations(customer_id);
CREATE INDEX IF NOT EXISTS idx_zones_name ON zones(name);
